ExecutorService pool = Executors.newFixedThreadPool(2);

CompletableFuture<Integer> applyDiscount(int total, ExecutorService pool) {
    // 割引の計算も別スレッドで行う(非同期を返す関数)
    return CompletableFuture.supplyAsync(() -> total >= 1000 ? total - 200 : total, pool);
