        try {
            return future.get(5, TimeUnit.SECONDS);
        } catch (TimeoutException e) {
            future.cancel(true);
            log.error("HSM timeout userId={}", userId, e);
            throw new KeyIssueException("hsm timeout", e);
        } catch (Exception e) {
            throw new KeyIssueException("hsm error", e);
        }
